 function start(){if(active)return;if(scores.some(x=>x>=5)){scores=[0,0];round=0;setScore()}active=true;locked=false;round++;clearTimers();drawDots();startBtn.textContent='ROUND IN PLAY';startBtn.disabled=true;const modes=['draw','mash','memory','target'];const mode=modes[Math.floor(Math.random()*modes.length)];if(mode==='draw')quickDraw();if(mode==='mash')mash();if(mode==='memory')memory();if(mode==='target')target()}
 function finishRound(winner,msg){if(locked)return;locked=true;clearTimers();if(winner!==null){scores[winner]++;setScore();beep(winner===0?650:820,.16)}const win=scores.findIndex(n=>n>=5);display.className='big-display result '+(winner===null?'':'confetti');display.textContent=win>=0?(win===0?'PLAYER ONE WINS!':'PLAYER TWO WINS!'):(winner===null?'DRAW!':`PLAYER ${winner+1} TAKES IT!`);copy.textContent=msg;title.textContent=win>=0?'CROWN CLAIMED':'ROUND OVER';roundline.textContent=win>=0?'DUEL COMPLETE':`ROUND ${round} COMPLETE`;status.textContent=win>=0?'CHAMPION UNLOCKED':'SCORE UPDATED';active=false;startBtn.disabled=false;startBtn.textContent=win>=0?'PLAY AGAIN ↻':'NEXT ROUND ↗';drawDots();if(win>=0)beep(980,.3)}
 function input(player){if(!active||locked)return;const now=performance.now();if(window.challenge==='draw'){if(!window.goAt){finishRound(1-player,`Too soon! Player ${player+1} jumped the gun.`);return}const time=now-window.goAt;window.times??=[null,null];if(window.times[player]!==null)return;window.times[player]=time;beep(480+player*120,.07);display.textContent=`${time} ms`;display.className='big-display';if(window.times[0]!==null&&window.times[1]!==null){finishRound(window.times[0]===window.times[1]?null:window.times[0]<window.times[1]?0:1,`P1 ${window.times[0]} ms  ·  P2 ${window.times[1]} ms`)}else{copy.textContent=`Player ${player+1} locked in! Other player, go!`}return}
 if(window.challenge==='mash'){window.taps[player]++;$('m'+player).style.width=Math.min(100,window.taps[player]/20*100)+'%';if(window.taps[player]>=20)finishRound(player,`Player ${player+1} hit 20 presses first!`);return}
-if(window.challenge==='memory'){if(player!==window.memoryTurn)return;const expected=window.seq[window.memIdx];if(player===0?false:false){};const keys=window.seq;const pressed=player===0?'A':'L';if(expected!==pressed){finishRound(1-player,`Player ${player+1} broke the sequence. Point to the rival!`);return}window.memIdx++;display.textContent=`${window.memIdx} / ${keys.length}`;beep(500+window.memIdx*60,.06);if(window.memIdx>=keys.length)finishRound(player,`Player ${player+1} repeated the full sequence!`);return}
+if(window.challenge==='memory')return;
 if(window.challenge==='target'){const wanted=window.targetKey;if(player===0?false:false){};const correct=player===0?['A','SPACE'].includes(window.lastKey):['L','ENTER'].includes(window.lastKey);if(correct)finishRound(player,`Player ${player+1} hit the target!`)} }
 function quickDraw(){window.challenge='draw';window.goAt=0;window.times=[null,null];title.textContent='QUICK DRAW';copy.textContent='Wait for the signal. Jump early and you lose!';display.textContent='WAIT…';display.className='big-display wait';roundline.textContent=`ROUND ${round} · REACTION RACE`;status.textContent='DON’T BLINK';const delay=1800+Math.random()*3000;later(()=>{if(!active)return;window.goAt=performance.now();display.textContent='GO!';display.className='big-display go';copy.textContent='Hit your key — now!';beep(900,.2)},delay)}
 function mash(){window.challenge='mash';window.taps=[0,0];title.textContent='BUTTON FRENZY';copy.textContent='Mash your button 20 times. Fastest fingers win.';display.textContent='3… 2… 1…';display.className='big-display ready';roundline.textContent=`ROUND ${round} · SPEED TEST`;status.textContent='MASH TO FILL YOUR BAR';action.innerHTML=`<div style="display:grid;gap:9px;text-align:left;margin:12px auto 0;max-width:410px"><div style="font:10px var(--mono);color:var(--pink)">P1 <div style="height:7px;background:#34313a;border-radius:8px;margin-top:5px;overflow:hidden"><i id="m0" style="display:block;width:0;height:100%;background:var(--pink);transition:width .08s"></i></div></div><div style="font:10px var(--mono);color:var(--cyan)">P2 <div style="height:7px;background:#34313a;border-radius:8px;margin-top:5px;overflow:hidden"><i id="m1" style="display:block;width:0;height:100%;background:var(--cyan);transition:width .08s"></i></div></div></div>`;later(()=>{if(active){display.textContent='MASH!';display.className='big-display go';beep(800,.15)}},900);later(()=>{if(active)finishRound(null,'Time! Nobody reached 20 presses. A clean draw.');},8500)}
 function memory(){window.challenge='memory';window.memoryTurn=Math.random()<.5?0:1;window.seq=Array.from({length:4},()=>Math.random()<.5?'A':'L');window.memIdx=0;title.textContent='MEMORY FLIP';copy.textContent=`Player ${window.memoryTurn+1}: watch the sequence, then repeat it.`;roundline.textContent=`ROUND ${round} · MEMORY TEST`;status.textContent=`P${window.memoryTurn+1} WATCH CLOSELY`;display.textContent='GET READY';display.className='big-display ready';let i=0;const show=()=>{if(!active)return;if(i<window.seq.length){display.textContent=window.seq[i]==='A'?'←':'→';display.style.color=window.seq[i]==='A'?'var(--pink)':'var(--cyan)';beep(window.seq[i]==='A'?430:730,.14);i++;later(show,650)}else{display.textContent='REPEAT!';display.style.color='';window.memoryTurn=window.memoryTurn;status.textContent=`PLAYER ${window.memoryTurn+1} REPEAT WITH ${window.memoryTurn===0?'A':'L'}`} };later(show,700);later(()=>{if(active&&window.memIdx<4)finishRound(1-window.memoryTurn,`Player ${window.memoryTurn+1} ran out of time.`)},9000)}

