 function target(){window.challenge='target';const choices=['A','L'];window.targetKey=choices[Math.floor(Math.random()*2)];title.textContent='COLOR CALL';copy.textContent='Hit only when your color appears. Wrong player? Point lost.';roundline.textContent=`ROUND ${round} · TARGET TEST`;status.textContent='WATCH THE COLOR';display.textContent='…';display.className='big-display wait';const wait=1300+Math.random()*2600;later(()=>{if(!active)return;window.targetPlayer=window.targetKey==='A'?0:1;display.textContent=window.targetPlayer===0?'P1!':'P2!';display.style.color=window.targetPlayer===0?'var(--pink)':'var(--cyan)';copy.textContent=`${window.targetPlayer===0?'PLAYER ONE':'PLAYER TWO'} — HIT YOUR KEY!`;window.targetLive=true;beep(800,.2);later(()=>{if(active&&window.targetLive)finishRound(1-window.targetPlayer,'Too slow! Your rival takes the point.')},1800)},wait)}
 function handleKey(e){const key=e.key.toUpperCase();let player=null;if(key==='A'||key===' '){player=0;if(key===' ')e.preventDefault()}else if(key==='L'||key==='ENTER'){player=1;if(key==='ENTER')e.preventDefault()}if(player===null)return;window.lastKey=key;if(window.challenge==='target'&&active&&window.targetLive){window.targetLive=false;if(player===window.targetPlayer)finishRound(player,`Player ${player+1} reacted in time!`);else finishRound(1-player,`Wrong button! Player ${player+1} called it.`);return}input(player)}document.addEventListener('keydown',handleKey);
 $('howBtn').onclick=()=>$('modal').classList.add('open');$('closeModal').onclick=()=>$('modal').classList.remove('open');$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.remove('open')};$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').textContent=`SOUND: ${sound?'ON':'OFF'}`;beep()};startBtn.onclick=()=>{startBtn.disabled=false;start()};document.querySelectorAll('.touch-btn').forEach(b=>b.onclick=()=>{const p=Number(b.dataset.player);window.lastKey=p===0?'A':'L';if(window.challenge==='target'&&active&&window.targetLive){window.targetLive=false;finishRound(p===window.targetPlayer?p:1-p,p===window.targetPlayer?`Player ${p+1} reacted in time!`:`Wrong button! Player ${p+1} called it.`)}else input(p)});
 // Touch controls are injected on compact screens; they share the keyboard's game logic.

