 const $=id=>document.getElementById(id);const s1=$('score1'),s2=$('score2'),title=$('title'),copy=$('copy'),display=$('display'),roundline=$('roundline'),status=$('status'),startBtn=$('startBtn'),dots=$('dots'),action=$('action');let scores=[0,0],round=0,active=false,locked=false,timers=[],sound=false,audio;
 const clearTimers=()=>{timers.forEach(clearTimeout);timers=[]};const later=(fn,ms)=>timers.push(setTimeout(fn,ms));const setScore=()=>{s1.textContent=scores[0];s2.textContent=scores[1]};function beep(freq=520,dur=.08){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=freq;o.connect(g);g.connect(audio.destination);g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+dur);o.start();o.stop(audio.currentTime+dur)}catch(e){}}
 function drawDots(){dots.innerHTML='';for(let i=0;i<5;i++){const d=document.createElement('i');if(i<round)d.className='done';if(i===round&&active)d.className='current';dots.append(d)}}
 function resetView(){clearTimers();active=false;locked=false;action.innerHTML='';title.textContent='Who’s got quick hands?';copy.textContent='Press start to deal the first random challenge.';display.textContent='✳';display.className='big-display';roundline.textContent='READY WHEN YOU ARE';status.textContent='A NEW CHALLENGE EVERY ROUND';startBtn.textContent='START DUEL ↗';drawDots()}
