 function finishRound(winner,msg){if(locked)return;locked=true;window.targetLive=false;clearTimers();if(winner!==null){scores[winner]++;setScore();beep(winner===0?650:820,.16)}const win=scores.findIndex(n=>n>=5);display.className='big-display result '+(winner===null?'':'confetti');display.textContent=win>=0?(win===0?'PLAYER ONE WINS!':'PLAYER TWO WINS!'):(winner===null?'DRAW!':`PLAYER ${winner+1} TAKES IT!`);copy.textContent=msg;title.textContent=win>=0?'CROWN CLAIMED':'ROUND OVER';roundline.textContent=win>=0?'DUEL COMPLETE':`ROUND ${round} COMPLETE`;status.textContent=win>=0?'CHAMPION UNLOCKED':'SCORE UPDATED';active=false;startBtn.disabled=false;startBtn.textContent=win>=0?'PLAY AGAIN ↻':'NEXT ROUND ↗';drawDots();if(win>=0)beep(980,.3)}
