+    '<div class="pad p1"><span class="pad-name">PLAYER ONE</span><span class="pad-keys">A / SPACE · TAP LEFT</span></div>' +
+    '<div class="pad p2"><span class="pad-name">PLAYER TWO</span><span class="pad-keys">L / ENTER · TAP RIGHT</span></div>';
+}
+function padMemory() {
+  pads.classList.remove('hidden');
+  pads.innerHTML =
+    '<div class="memgroup p1"><span class="memlabel">P1 · A / D</span><div class="membtns">' +
+      '<button data-p="0" data-d="L" disabled>←</button><button data-p="0" data-d="R" disabled>→</button>' +
+    '</div></div>' +
+    '<div class="memgroup p2"><span class="memlabel">P2 · J / L</span><div class="membtns">' +
+      '<button data-p="1" data-d="L" disabled>←</button><button data-p="1" data-d="R" disabled>→</button>' +
+    '</div></div>';
+  pads.querySelectorAll('.membtns button').forEach(b => {
+    b.addEventListener('pointerdown', ev => {
+      ev.preventDefault();
+      memoryTap(+b.dataset.p, b.dataset.d);
+    });
+  });
+}
+
+function drawDots() {
+  dots.innerHTML = '';
+  const played = Math.min(G.round, 5);
+  for (let i = 0; i < 5; i++) {
+    const d = document.createElement('i');
+    if (i < played) d.className = 'done';
+    if (G.active && i === played - 1) d.className = 'current';
+    dots.append(d);
+  }
+}
+
+function start(forced) {
+  if (G.active) return;
+  if (G.scores.some(n => n >= 5)) {
+    G.scores = [0, 0];
+    G.round = 0;
+    G.prev = null;
+    setScore();
+  }
+  G.active = true;
+  G.locked = false;
+  G.holdCount = [0, 0];
+  G.cue = false;
+  G.memReady = false;
+  G.round++;
+  clearTimers();
+  action.innerHTML = '';
+  disp.style.color = '';
+  pads.classList.remove('hidden', 'idle');
+  hero.classList.add('playing');
+  hero.classList.remove('flash');
+  padDuel();
+  startBtn.disabled = true;
+  startBtn.textContent = 'ROUND IN PLAY';
+  drawDots();
+
+  const all = ['draw', 'mash', 'memory', 'target', 'bull', 'hold', 'odd', 'numbers'];
+  const pool = all.filter(m => m !== G.prev);
+  const mode = forced || pick(pool.length ? pool : all);
+  G.prev = mode;
+  G.mode = mode;
+  ({ draw: quickDraw, mash: mashRun, memory: memory, target: target,
+     bull: bullRun, hold: holdLine, odd: oddOne, numbers: numberHunt })[mode]();
+}
+
+function finishRound(winner, msg, bigText) {
+  if (!G.active || G.locked) return;
+  G.locked = true;
+  G.cue = false;
+  if (G.mode === 'hold') paintHold();
+  clearTimers();
+  G.mode = null;
+
+  if (winner !== null) {
+    G.scores[winner]++;
+    setScore();
+    beep(winner === 0 ? 660 : 840, 0.16);
+  }
+  const champ = G.scores.findIndex(n => n >= 5);
+  disp.className = 'big-display result' + (winner === null ? '' : ' confetti');
+  disp.style.color = '';
+  if (champ >= 0) disp.textContent = champ === 0 ? 'PLAYER ONE WINS' : 'PLAYER TWO WINS';
+  else if (bigText) disp.textContent = bigText;
+  else if (winner === null) disp.textContent = 'DRAW!';
+  else disp.textContent = 'PLAYER ' + (winner + 1) + ' SCORES';
+
+  copy.textContent = msg;
+  title.textContent = champ >= 0 ? 'CROWN CLAIMED' : 'ROUND OVER';
+  roundline.textContent = champ >= 0 ? 'MATCH COMPLETE' : 'ROUND ' + G.round + ' COMPLETE';
+  statusEl.textContent = champ >= 0 ? 'CHAMPION · FIRST TO 5' : 'SCORE UPDATED';
+  startBtn.disabled = false;
+  startBtn.textContent = champ >= 0 ? 'PLAY AGAIN ↻' : 'NEXT ROUND ↗';
+  pads.classList.add('idle');
+  G.active = false;
+  drawDots();
+  if (champ >= 0) {
+    beep(990, 0.3);
+    later(() => beep(1280, 0.35), 160);
+  }
+}
+
+function press(p) {
+  if (!G.active || G.locked) return;
+  flashPad(p);
+  switch (G.mode) {
+    case 'draw': {
+      if (!G.goAt) { finishRound(1 - p, 'Too soon! Player ' + (p + 1) + ' jumped the gun.'); return; }
+      const ms = Math.max(1, Math.round(performance.now() - G.goAt));
+      finishRound(p, 'Player ' + (p + 1) + ' reacted in ' + ms + ' ms.', ms + ' ms');
+      break;
+    }
+    case 'mash': {
+      G.taps[p]++;
+      const bar = $('m' + p), count = $('c' + p);
+      if (bar) bar.style.width = Math.min(100, G.taps[p] / MASH_GOAL * 100) + '%';
+      if (count) count.textContent = G.taps[p];
+      beep(400 + p * 140, 0.035);
+      if (G.taps[p] >= MASH_GOAL) finishRound(p, 'Player ' + (p + 1) + ' hit ' + MASH_GOAL + ' taps first!');
+      break;
+    }
+    case 'target': {
+      if (!G.live) { finishRound(1 - p, 'Player ' + (p + 1) + ' jumped before the cue.'); return; }
+      if (p === G.wanted) finishRound(p, 'Player ' + (p + 1) + ' reacted first!');
+      else finishRound(1 - p, 'Wrong side! Player ' + (p + 1) + ' loses the point.');
+      break;
+    }
+    case 'bull': bullLock(p); break;
+    case 'hold': holdDown(p); break;
+  }
+}
+
+function release(p) {
+  if (!G.active || G.locked || G.mode !== 'hold') return;
+  holdUp(p);
+}
+//PART2
 </script>
 </body>
 </html>

