function quickDraw() {
  G.goAt = 0;
  title.textContent = 'QUICK DRAW';
  copy.textContent = 'Wait for the flash, then tap. Jump early and the point goes to your rival.';
  show('WAIT…', 'wait');
  roundline.textContent = 'ROUND ' + G.round + ' · REACTION RACE';
  statusEl.textContent = 'DON’T BLINK';
  const delay = 1600 + Math.random() * 2600;
  later(() => {
    if (!G.active || G.locked) return;
    G.goAt = performance.now();
    show('GO!', 'go');
    copy.textContent = 'Tap now — first to react wins!';
    beep(950, 0.18);
  }, delay);
  later(() => {
    if (G.active && G.mode === 'draw' && G.goAt) finishRound(null, 'Too slow! Nobody tapped in time.');
  }, delay + 3800);
}

function mashRun() {
  G.taps = [0, 0];
  title.textContent = 'BUTTON FRENZY';
  copy.textContent = 'Mash your side 20 times. Both players can tap at once — no waiting!';
  show('MASH!', 'go');
  roundline.textContent = 'ROUND ' + G.round + ' · SPEED TEST';
  statusEl.textContent = '20 TAPS WINS';
  action.innerHTML =
    '<div class="bars">' +
      '<div class="bar p1"><div class="barlabel"><span>PLAYER ONE</span><b id="c0">0</b></div><div class="track"><i id="m0"></i></div></div>' +
      '<div class="bar p2"><div class="barlabel"><span>PLAYER TWO</span><b id="c1">0</b></div><div class="track"><i id="m1"></i></div></div>' +
    '</div>';
  later(() => {
    if (!G.active || G.mode !== 'mash') return;
    if (G.taps[0] === G.taps[1]) finishRound(null, 'Time! ' + G.taps[0] + ' taps each. Draw!');
    else {
      const w = G.taps[0] > G.taps[1] ? 0 : 1;
      finishRound(w, 'Time! P1 ' + G.taps[0] + ' · P2 ' + G.taps[1] + '.');
    }
  }, 9000);
}

function memory() {
  G.memTurn = pick([0, 1]);
  G.seq = Array.from({ length: 4 }, () => pick(['L', 'R']));
  G.memIdx = 0;
  G.memReady = false;
  title.textContent = 'MEMORY FLIP';
  copy.textContent = 'Player ' + (G.memTurn + 1) + ', memorize the arrows.';
  show('WATCH', 'ready');
  roundline.textContent = 'ROUND ' + G.round + ' · MEMORY';
  statusEl.textContent = 'PLAYER ' + (G.memTurn + 1) + ' WATCHES';
  padMemory();
  let i = 0;
  const step = () => {
    if (!G.active || G.locked) return;
    if (i < G.seq.length) {
      const d = G.seq[i];
      show(d === 'L' ? '←' : '→', '', d === 'L' ? 'var(--pink)' : 'var(--cyan)');
      beep(d === 'L' ? 420 : 720, 0.13);
      i++;
      later(() => { if (G.active && !G.locked) show('·', 'wait'); }, 330);
      later(step, 640);
    } else {
      show('REPEAT!', 'go');
      copy.textContent = 'Player ' + (G.memTurn + 1) + ': repeat with ' +
        (G.memTurn === 0 ? 'A / D' : 'J / L') + ' or the arrow pads.';
      statusEl.textContent = 'PLAYER ' + (G.memTurn + 1) + ' REPEATS';
      G.memIdx = 0;
      G.memReady = true;
      const group = pads.querySelector('.memgroup.p' + (G.memTurn + 1));
      if (group) {
        group.classList.add('live');
        group.querySelectorAll('button').forEach(b => { b.disabled = false; });
      }
      later(() => {
        if (G.active && !G.locked) finishRound(1 - G.memTurn, 'Player ' + (G.memTurn + 1) + ' ran out of time.');
      }, 9000);
    }
  };
  later(step, 700);
}

function memoryTap(p, dir) {
  if (!G.active || G.locked || G.mode !== 'memory' || !G.memReady) return;
  if (p !== G.memTurn || G.memIdx >= G.seq.length) return;
  if (dir !== G.seq[G.memIdx]) {
    finishRound(1 - p, 'Player ' + (p + 1) + ' broke the sequence. Point to the rival!');
    return;
  }
  G.memIdx++;
  beep(500 + G.memIdx * 70, 0.07);
  show(G.memIdx + ' / ' + G.seq.length, '', '');
  if (G.memIdx === G.seq.length) finishRound(p, 'Player ' + (p + 1) + ' repeated the whole sequence!');
}

function target() {
  G.live = false;
  G.wanted = pick([0, 1]);
  title.textContent = 'COLOR CALL';
  copy.textContent = 'Only the called player taps. Any wrong tap gives away the point.';
  show('…', 'wait');
  roundline.textContent = 'ROUND ' + G.round + ' · TARGET';
  statusEl.textContent = 'WATCH FOR YOUR NAME';
  const wait = 1200 + Math.random() * 2400;
  later(() => {
    if (!G.active || G.locked) return;
    G.live = true;
    show(G.wanted === 0 ? 'P1!' : 'P2!', 'go',
      G.wanted === 0 ? 'var(--pink)' : 'var(--cyan)');
    copy.textContent = (G.wanted === 0 ? 'PLAYER ONE' : 'PLAYER TWO') + ' — tap now!';
    beep(880, 0.18);
    later(() => {
      if (G.active && G.live) {
        G.live = false;
        finishRound(1 - G.wanted, 'Too slow! The point goes to the rival.');
      }
    }, 1700);
  }, wait);
}

function bullRun() {
  const positions = [0.32 + Math.random() * 0.36, 0.32 + Math.random() * 0.36];
  const dirs = [pick([-1, 1]), pick([-1, 1])];
  const speeds = [0.5 + Math.random() * 0.3, 0.5 + Math.random() * 0.3];
  G.bull = { pos: positions, dir: dirs, speed: speeds, locked: [false, false], last: performance.now(), markers: [] };
  title.textContent = 'BULLSEYE';
  copy.textContent = 'Tap to freeze your slider. Closest to the gold centre wins.';
  show('TAP TO LOCK', 'ready');
  roundline.textContent = 'ROUND ' + G.round + ' · TIMING';
  statusEl.textContent = 'CLOSEST TO THE CENTRE';
  action.innerHTML =
    '<div class="bulls">' +
      '<div class="bullrow p1"><span class="bullname">P1</span><div class="track"><i class="center"></i><i class="marker" id="bm0"></i></div></div>' +
      '<div class="bullrow p2"><span class="bullname">P2</span><div class="track"><i class="center"></i><i class="marker" id="bm1"></i></div></div>' +
    '</div><p class="tiny">BOTH PLAYERS CAN FREEZE AT THE SAME TIME</p>';
  G.bull.markers = [$('bm0'), $('bm1')];
  G.bull.markers.forEach((m, p) => { m.style.left = (G.bull.pos[p] * 100) + '%'; });
  G.raf = requestAnimationFrame(bullFrame);
  later(() => {
    if (G.active && G.mode === 'bull' && !G.locked) {
      G.bull.locked = [true, true];
      resolveBull();
    }
  }, 7000);
}

function bullFrame(ts) {
  if (!G.active || G.locked || G.mode !== 'bull' || !G.bull) return;
  const dt = Math.min(50, ts - G.bull.last) / 1000;
  G.bull.last = ts;
  for (let p = 0; p < 2; p++) {
    if (G.bull.locked[p]) continue;
    let v = G.bull.pos[p] + G.bull.dir[p] * G.bull.speed[p] * dt;
    if (v > 1) { v = 2 - v; G.bull.dir[p] *= -1; }
    if (v < 0) { v = -v; G.bull.dir[p] *= -1; }
    G.bull.pos[p] = v;
    if (G.bull.markers[p]) G.bull.markers[p].style.left = (v * 100) + '%';
  }
  G.raf = requestAnimationFrame(bullFrame);
}

function bullLock(p) {
  if (!G.bull || G.bull.locked[p]) return;
  G.bull.locked[p] = true;
  const m = G.bull.markers[p];
  if (m) m.classList.add('locked');
  beep(430 + p * 180, 0.08);
  if (G.bull.locked[0] && G.bull.locked[1]) resolveBull();
}

function resolveBull() {
  if (!G.active || G.locked || !G.bull) return;
  const d = [Math.abs(G.bull.pos[0] - 0.5), Math.abs(G.bull.pos[1] - 0.5)];
  const txt = 'P1 ' + (d[0] * 100).toFixed(0) + '% off · P2 ' + (d[1] * 100).toFixed(0) + '% off.';
  if (Math.abs(d[0] - d[1]) < 0.005) finishRound(null, txt + ' Dead heat!');
  else finishRound(d[0] < d[1] ? 0 : 1, txt);
}

function paintHold() {
  [0, 1].forEach(p => {
    const el = $('h' + (p + 1));
    if (el) {
      const on = G.holdCount[p] > 0;
      el.textContent = 'P' + (p + 1) + ' ' + (on ? 'HOLDING' : 'WAITING');
      el.classList.toggle('on', on);
    }
    const pad = pads.querySelector('.pad.p' + (p + 1));
    if (pad) pad.classList.toggle('holding', G.holdCount[p] > 0);
  });
}

function holdDown(p) {
  G.holdCount[p]++;
  if (G.holdCount[p] === 1) beep(520 + p * 90, 0.06);
  paintHold();
}

function holdUp(p) {
  if (G.holdCount[p] <= 0) return;
  G.holdCount[p]--;
  paintHold();
  if (G.holdCount[p] > 0) return;
  if (!G.cue) { finishRound(1 - p, 'Player ' + (p + 1) + ' let go too soon!'); return; }
  finishRound(p, 'Player ' + (p + 1) + ' let go right on the flash!');
}

function holdLine() {
  G.holdCount = [0, 0];
  G.cue = false;
  title.textContent = 'HOLD THE LINE';
  copy.textContent = 'Press and hold your side. Let go the instant the screen flashes — too early loses.';
  show('HOLD ON', 'ready');
  roundline.textContent = 'ROUND ' + G.round + ' · NERVES';
  statusEl.textContent = 'BOTH PLAYERS HOLD';
  action.innerHTML =
    '<div class="holdrow"><span class="holdpill p1" id="h1">P1 WAITING</span>' +
    '<span class="holdpill p2" id="h2">P2 WAITING</span></div>';
  padDuel();
  const delay = 2200 + Math.random() * 3200;
  later(() => {
    if (!G.active || G.locked) return;
    if (G.holdCount[0] === 0 && G.holdCount[1] === 0) { finishRound(null, 'Nobody was holding. Draw!'); return; }
    if (G.holdCount[0] === 0) { finishRound(1, 'Player 1 never held on.'); return; }
    if (G.holdCount[1] === 0) { finishRound(0, 'Player 2 never held on.'); return; }
    G.cue = true;
    show('LET GO!', 'go');
    copy.textContent = 'Release now! First finger up wins.';
    statusEl.textContent = 'RELEASE!';
    flashScreen();
    beep(980, 0.22);
    later(() => {
      if (G.active && G.mode === 'hold') finishRound(null, 'Both held on. Draw!');
    }, 2400);
  }, delay);
}
//PART3

