+      '<div class="bullrow p2"><span class="bullname">P2</span><div class="track"><i class="center"></i><i class="marker" id="bm1"></i></div></div>' +
+    '</div><p class="tiny">BOTH PLAYERS CAN FREEZE AT THE SAME TIME</p>';
+  G.bull.markers = [$('bm0'), $('bm1')];
+  G.bull.markers.forEach((m, p) => { m.style.left = (G.bull.pos[p] * 100) + '%'; });
+  G.raf = requestAnimationFrame(bullFrame);
+  later(() => {
+    if (G.active && G.mode === 'bull' && !G.locked) {
+      G.bull.locked = [true, true];
+      resolveBull();
+    }
+  }, 7000);
+}
+
+function bullFrame(ts) {
+  if (!G.active || G.locked || G.mode !== 'bull' || !G.bull) return;
+  const dt = Math.min(50, ts - G.bull.last) / 1000;
+  G.bull.last = ts;
+  for (let p = 0; p < 2; p++) {
+    if (G.bull.locked[p]) continue;
+    let v = G.bull.pos[p] + G.bull.dir[p] * G.bull.speed[p] * dt;
+    if (v > 1) { v = 2 - v; G.bull.dir[p] *= -1; }
+    if (v < 0) { v = -v; G.bull.dir[p] *= -1; }
+    G.bull.pos[p] = v;
+    if (G.bull.markers[p]) G.bull.markers[p].style.left = (v * 100) + '%';
+  }
+  G.raf = requestAnimationFrame(bullFrame);
+}
+
+function bullLock(p) {
+  if (!G.bull || G.bull.locked[p]) return;
+  G.bull.locked[p] = true;
+  const m = G.bull.markers[p];
+  if (m) m.classList.add('locked');
+  beep(430 + p * 180, 0.08);
+  if (G.bull.locked[0] && G.bull.locked[1]) resolveBull();
+}
+
+function resolveBull() {
+  if (!G.active || G.locked || !G.bull) return;
+  const d = [Math.abs(G.bull.pos[0] - 0.5), Math.abs(G.bull.pos[1] - 0.5)];
+  const txt = 'P1 ' + (d[0] * 100).toFixed(0) + '% off · P2 ' + (d[1] * 100).toFixed(0) + '% off.';
+  if (Math.abs(d[0] - d[1]) < 0.005) finishRound(null, txt + ' Dead heat!');
+  else finishRound(d[0] < d[1] ? 0 : 1, txt);
+}
+
+function paintHold() {
+  [0, 1].forEach(p => {
+    const el = $('h' + (p + 1));
+    if (el) {
+      const on = G.holdCount[p] > 0;
+      el.textContent = 'P' + (p + 1) + ' ' + (on ? 'HOLDING' : 'WAITING');
+      el.classList.toggle('on', on);
+    }
+    const pad = pads.querySelector('.pad.p' + (p + 1));
+    if (pad) pad.classList.toggle('holding', G.holdCount[p] > 0);
+  });
+}
+
+function holdDown(p) {
+  G.holdCount[p]++;
+  if (G.holdCount[p] === 1) beep(520 + p * 90, 0.06);
+  paintHold();
+}
+
+function holdUp(p) {
+  if (G.holdCount[p] <= 0) return;
+  G.holdCount[p]--;
+  paintHold();
+  if (G.holdCount[p] > 0) return;
+  if (!G.cue) { finishRound(1 - p, 'Player ' + (p + 1) + ' let go too soon!'); return; }
+  finishRound(p, 'Player ' + (p + 1) + ' let go right on the flash!');
+}
+
+function holdLine() {
+  G.holdCount = [0, 0];
+  G.cue = false;
+  title.textContent = 'HOLD THE LINE';
+  copy.textContent = 'Press and hold your side. Let go the instant the screen flashes — too early loses.';
+  show('HOLD ON', 'ready');
+  roundline.textContent = 'ROUND ' + G.round + ' · NERVES';
+  statusEl.textContent = 'BOTH PLAYERS HOLD';
+  action.innerHTML =
+    '<div class="holdrow"><span class="holdpill p1" id="h1">P1 WAITING</span>' +
+    '<span class="holdpill p2" id="h2">P2 WAITING</span></div>';
+  padDuel();
+  const delay = 2200 + Math.random() * 3200;
+  later(() => {
+    if (!G.active || G.locked) return;
+    if (G.holdCount[0] === 0 && G.holdCount[1] === 0) { finishRound(null, 'Nobody was holding. Draw!'); return; }
+    if (G.holdCount[0] === 0) { finishRound(1, 'Player 1 never held on.'); return; }
+    if (G.holdCount[1] === 0) { finishRound(0, 'Player 2 never held on.'); return; }
+    G.cue = true;
+    show('LET GO!', 'go');
+    copy.textContent = 'Release now! First finger up wins.';
+    statusEl.textContent = 'RELEASE!';
+    flashScreen();
+    beep(980, 0.22);
+    later(() => {
+      if (G.active && G.mode === 'hold') finishRound(null, 'Both held on. Draw!');
+    }, 2400);
+  }, delay);
+}
+//PART3
 </script>
 </body>
 </html>

