function oddOne() {
  pads.classList.add('hidden');
  const pairs = [['●', '○'], ['▲', '△'], ['◆', '◇'], ['★', '☆'], ['■', '□'], ['♥', '♡'], ['☾', '☀'], ['✚', '✖']];
  const pair = pick(pairs), base = pair[0], odd = pair[1];
  const oddAt = Math.floor(Math.random() * 6);
  const cells = Array.from({ length: 6 }, (_, i) => i === oddAt ? odd : base);
  title.textContent = 'ODD ONE OUT';
  copy.textContent = 'One tile is different. Tap it before your rival — a wrong tap gives away the point.';
  show('FIND IT', 'ready');
  roundline.textContent = 'ROUND ' + G.round + ' · PERCEPTION';
  statusEl.textContent = 'TAP THE ODD TILE';
  const grid = p => '<div class="ogrid p' + (p + 1) + '">' +
    cells.map((c, i) => '<button data-p="' + p + '" data-i="' + i + '">' + c + '</button>').join('') + '</div>';
  action.innerHTML =
    '<div class="ogrids">' +
      '<div class="oside p1"><span>PLAYER ONE</span>' + grid(0) + '</div>' +
      '<div class="oside p2"><span>PLAYER TWO</span>' + grid(1) + '</div>' +
    '</div>';
  action.querySelectorAll('button').forEach(b => {
    b.addEventListener('pointerdown', ev => {
      ev.preventDefault();
      if (!G.active || G.locked || G.mode !== 'odd') return;
      const p = +b.dataset.p, i = +b.dataset.i;
      if (i === oddAt) finishRound(p, 'Player ' + (p + 1) + ' found the odd one out!');
      else finishRound(1 - p, 'Wrong tile! Player ' + (p + 1) + ' loses the point.');
    });
  });
  later(() => {
    if (G.active && G.mode === 'odd') finishRound(null, 'Nobody found it in time. Draw!');
  }, 10000);
}

function numberHunt() {
  pads.classList.add('hidden');
  const order = [1, 2, 3, 4, 5, 6].sort(() => Math.random() - 0.5);
  G.num = { next: [1, 1], lock: [false, false] };
  title.textContent = 'NUMBER RUSH';
  copy.textContent = 'Tap 1 → 6 in order. Both grids are live at once. Wrong taps cost half a second.';
  show('1 → 6', 'ready');
  roundline.textContent = 'ROUND ' + G.round + ' · SPEED + ORDER';
  statusEl.textContent = 'BOTH GRIDS LIVE';
  const grid = p => '<div class="ogrid numgrid p' + (p + 1) + '">' +
    order.map(n => '<button data-p="' + p + '" data-v="' + n + '">' + n + '</button>').join('') + '</div>';
  action.innerHTML =
    '<div class="ogrids">' +
      '<div class="oside p1"><span>PLAYER ONE</span>' + grid(0) + '</div>' +
      '<div class="oside p2"><span>PLAYER TWO</span>' + grid(1) + '</div>' +
    '</div>';
  action.querySelectorAll('button').forEach(b => {
    b.addEventListener('pointerdown', ev => {
      ev.preventDefault();
      numTap(+b.dataset.p, b);
    });
  });
  later(() => {
    if (G.active && G.mode === 'numbers') finishRound(null, 'Time! Neither grid was finished.');
  }, 12000);
}

function numTap(p, btn) {
  if (!G.active || G.locked || G.mode !== 'numbers' || !G.num) return;
  if (G.num.lock[p]) return;
  const v = +btn.dataset.v;
  if (v !== G.num.next[p]) {
    G.num.lock[p] = true;
    btn.classList.add('wrong');
    beep(180, 0.12);
    later(() => {
      btn.classList.remove('wrong');
      if (G.num) G.num.lock[p] = false;
    }, 450);
    return;
  }
  btn.classList.add('done');
  btn.disabled = true;
  beep(480 + p * 130, 0.05);
  G.num.next[p]++;
  if (G.num.next[p] > 6) finishRound(p, 'Player ' + (p + 1) + ' counted to six first!');
}

/* ---------- input: multi-touch, mouse, keyboard ---------- */
const owners = new Map();

document.addEventListener('pointerdown', e => {
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  if (e.target.closest('button,a,input,select,textarea,label,.modal')) return;
  if (!e.target.closest('.stage,.pads')) return;
  if (!G.active || G.locked) return;
  e.preventDefault();
  const p = e.clientX < window.innerWidth / 2 ? 0 : 1;
  owners.set(e.pointerId, p);
  press(p);
}, { passive: false });

function pointerEnd(e) {
  const p = owners.get(e.pointerId);
  if (p === undefined) return;
  owners.delete(e.pointerId);
  release(p);
}
document.addEventListener('pointerup', pointerEnd);
document.addEventListener('pointercancel', pointerEnd);
window.addEventListener('blur', () => {
  owners.forEach(p => release(p));
  owners.clear();
});

document.addEventListener('keydown', e => {
  if (e.repeat) return;
  const k = e.key.toUpperCase();
  if (k === 'A' || k === ' ' || k === 'D' || k === 'J' || k === 'L' || k === 'ENTER') e.preventDefault();
  if (G.mode === 'memory' && G.active && !G.locked) {
    if (k === 'A' || k === 'D') memoryTap(0, k === 'A' ? 'L' : 'R');
    else if (k === 'J' || k === 'L') memoryTap(1, k === 'J' ? 'L' : 'R');
    return;
  }
  if (k === 'A' || k === ' ') press(0);
  else if (k === 'L' || k === 'ENTER') press(1);
});

document.addEventListener('keyup', e => {
  const k = e.key.toUpperCase();
  if (k === 'A' || k === ' ') release(0);
  else if (k === 'L' || k === 'ENTER') release(1);
});

/* ---------- chrome ---------- */
$('howBtn').onclick = () => $('modal').classList.add('open');
$('closeModal').onclick = () => $('modal').classList.remove('open');
$('modal').onclick = e => { if (e.target === $('modal')) $('modal').classList.remove('open'); };
$('soundBtn').onclick = () => {
  G.sound = !G.sound;
  $('soundBtn').textContent = 'SOUND: ' + (G.sound ? 'ON' : 'OFF');
  beep();
};
startBtn.onclick = () => start();

function resetView() {
  clearTimers();
  G.active = false;
  G.locked = true;
  G.mode = null;
  G.prev = null;
  G.round = 0;
  G.scores = [0, 0];
  G.memReady = false;
  G.cue = false;
  hero.classList.remove('playing', 'flash');
  action.innerHTML = '';
  pads.classList.remove('hidden', 'idle');
  padDuel();
  title.textContent = 'Who’s got quick hands?';
  copy.textContent = 'Press start to deal a random challenge.';
  show('✳', '', '');
  roundline.textContent = 'READY WHEN YOU ARE';
  statusEl.textContent = '8 CHALLENGES · FIRST TO 5';
  startBtn.textContent = 'START DUEL ↗';
  startBtn.disabled = false;
  setScore();
  drawDots();
}

window.CHAOS = { start };

resetView();
})();

