import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';

const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
const page = await context.newPage();
await page.goto('http://localhost:3002/');
await page.evaluate(() => window.CHAOS.start('mash'));
const cdp = await context.newCDPSession(page);
let id = 1;
for (let i = 0; i < 3; i++) {
  await cdp.send('Input.dispatchTouchEvent', {
    type: 'touchStart',
    touchPoints: [{ x: 80, y: 640, id: id++ }, { x: 310, y: 640, id: id++ }]
  });
  await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
}
await page.waitForTimeout(100);
const taps = await page.evaluate(() => [document.getElementById('c0').textContent, document.getElementById('c1').textContent]);
console.log('mash taps', taps);

await page.reload();
await page.evaluate(() => window.CHAOS.start('hold'));
await cdp.send('Input.dispatchTouchEvent', {
  type: 'touchStart',
  touchPoints: [{ x: 80, y: 640, id: 51 }, { x: 310, y: 640, id: 52 }]
});
await page.waitForTimeout(200);
console.log('pills', await page.evaluate(() => [document.getElementById('h1').textContent, document.getElementById('h2').textContent]));
let cue = '';
for (let i = 0; i < 80; i++) {
  cue = await page.evaluate(() => document.querySelector('.big-display').textContent);
  if (cue === 'LET GO!') break;
  await page.waitForTimeout(60);
}
await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [{ x: 310, y: 640, id: 52 }] });
await page.waitForTimeout(150);
console.log('hold', cue, await page.evaluate(() => [document.querySelector('.big-display').textContent, document.getElementById('score1').textContent, document.getElementById('score2').textContent]));
await browser.close();

