input.content:
import { chromium } from '/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core/index.mjs';

const browser = await chromium.launch({ executablePath: '/usr/bin/google-chrome', headless: true });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });
const page = await context.newPage();
const errors = [];
page.on('pageerror', e => errors.push(String(e)));
await page.goto('http://localhost:3002/');

const ev = (t, id, x) => page.evaluate(([t, id, x]) => {
  const st = document.querySelector('.stage');
  const type = t === 'd' ? 'pointerdown' : 'pointerup';
  st.dispatchEvent(new PointerEvent(type, { bubbles: true, pointerId: id, pointerType: 'touch', clientX: x, clientY: 500, button: 0 }));
}, [t, id, x]);
const disp = () => page.evaluate(() => document.querySelector('.big-display').textContent);
const waitFor = async (txt, ms = 7000) => {
  const t0 = Date.now();
  while (Date.now() - t0 < ms) {
    if (await disp() === txt) return true;
    await page.waitForTimeout(50);
  }
  return false;
};
const reset = () => page.evaluate(() => { window.CHAOS.state.scores = [0, 0]; });

for (const mode of ['draw', 'mash', 'memory', 'target', 'bull', 'hold', 'odd', 'numbers']) {
  await reset();
  await page.evaluate(m => window.CHAOS.start(m), mode);
  if (mode === 'draw') await ev('d', 1, 80);
  if (mode === 'mash') for (let i = 0; i < 20; i++) await ev('d', 2, 80);
  if (mode === 'memory') {
    await waitFor('REPEAT!');
    const seq = await page.evaluate(() => [window.CHAOS.state.memTurn, window.CHAOS.state.seq.slice()]);
    for (const d of seq[1]) {
      await page.evaluate(([p, d]) => {
        document.querySelector('.memgroup.p' + (p + 1) + ' button[data-d="' + d + '"]')
          .dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerId: 3, pointerType: 'touch' }));
      }, [seq[0], d]);
    }
  }
  if (mode === 'target') {
    const t0 = Date.now();
    while (Date.now() - t0 < 6000) {
      const d = await disp();
      if (d === 'P1!' || d === 'P2!') { await ev('d', 4, d === 'P1!' ? 80 : 320); break; }
      await page.waitForTimeout(50);
    }
  }
  if (mode === 'bull') { await page.waitForTimeout(400); await ev('d', 5, 80); await ev('d', 6, 320); }
  if (mode === 'hold') {
    await ev('d', 7, 80); await ev('d', 8, 320);
    const t0 = Date.now();
    while (Date.now() - t0 < 7000) {
      if (await disp() === 'LET GO!') { await ev('u', 7, 80); break; }
      await page.waitForTimeout(50);
    }
  }
  if (mode === 'odd') {
    const idx = await page.evaluate(() => {
      const btns = [...document.querySelectorAll('.oside.p1 .ogrid button')];
      const counts = {};
      btns.forEach(b => counts[b.textContent] = (counts[b.textContent] || 0) + 1);
      const base = Object.keys(counts).find(k => counts[k] === 5);
      return btns.findIndex(b => b.textContent !== base);
    });
    await page.evaluate(i => {
      document.querySelectorAll('.oside.p1 .ogrid button')[i]
        .dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerId: 9, pointerType: 'touch' }));
    }, idx);
  }
  if (mode === 'numbers') {
    for (let n = 1; n <= 6; n++) {
      await page.evaluate(n => {
        [...document.querySelectorAll('.oside.p1 .ogrid button')].find(b => b.dataset.v === String(n))
          .dispatchEvent(new PointerEvent('pointerdown', { bubbles: true, pointerId: 10 + n, pointerType: 'touch' }));
      }, n);
    }
  }
  await page.waitForTimeout(150);
  const result = await page.evaluate(() => ({
    disp: document.querySelector('.big-display').textContent,
    active: window.CHAOS.state.active,
    scores: window.CHAOS.state.scores.slice()
  }));
  console.log(mode, JSON.stringify(result));
}

console.log('errors', errors);
await browser.close();

